static void *mqtt_worker(void *arg)
{
    struct mqtt_ctx *ctx = arg;
    struct mqtt_client client;
    unsigned backoff = 1;       /* exponential backoff seconds, reset on success */

    syslog(LOG_INFO, "[claude-mqtt] worker entered\n");

    while (g_running) {
        /* 1. Establish TCP to the broker (waits for Wi-Fi/DNS to come up). */
        int fd = open_socket();
        if (fd < 0) {
            syslog(LOG_INFO, "[claude-mqtt] retry in %us\n", backoff);
            sleep(backoff);
            if (backoff < 30) backoff *= 2;
            continue;
        }

        /* 2. Fresh client each connection: init + CONNECT + SUBSCRIBE. */
        if (mqtt_init(&client, fd, ctx->sendbuf, sizeof(ctx->sendbuf),
                      ctx->recvbuf, sizeof(ctx->recvbuf), publish_cb) != MQTT_OK) {
            syslog(LOG_INFO, "[claude-mqtt] mqtt_init failed, retry in %us\n", backoff);
            close(fd);
            sleep(backoff);
            if (backoff < 30) backoff *= 2;
            continue;
        }
        mqtt_connect(&client, "vela-home-scense", NULL, NULL, 0, NULL, NULL,
                     MQTT_CONNECT_CLEAN_SESSION, 60);
        if (client.error != MQTT_OK) {
            syslog(LOG_INFO, "[claude-mqtt] connect failed, retry in %us\n", backoff);
            close(fd);
            sleep(backoff);
            if (backoff < 30) backoff *= 2;
            continue;
        }
        mqtt_subscribe(&client, TOPIC, 0);
        syslog(LOG_INFO, "[claude-mqtt] connected + subscribed, topic=%s\n", TOPIC);
        backoff = 1;            /* connected OK: reset backoff */

        /* 3. Pump traffic until an error, then reconnect with backoff. */
